def resolve(path, cwd, links):
    # Validate cwd
    if not cwd.startswith('/'):
        return None

    # Normalize cwd to remove trailing slash (except for root)
    if cwd != '/' and cwd.endswith('/'):
        return None

    # Start with cwd if path is relative
    if not path.startswith('/'):
        current = cwd
    else:
        current = ''

    # Split path into components
    components = path.split('/')

    # Track number of links followed
    link_count = 0

    i = 0
    while i < len(components):
        component = components[i]

        # Skip empty components and '.'
        if component == '' or component == '.':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            # Move to parent
            if current == '/':
                # Stay at root
                pass
            else:
                # Remove last component
                last_slash = current.rfind('/')
                if last_slash == 0:
                    current = '/'
                else:
                    current = current[:last_slash]
            i += 1
            continue

        # Append component
        if current == '/':
            current = '/' + component
        else:
            current = current + '/' + component

        # Check if current path is a symlink
        if current in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[current]

            # Get remaining components after current
            remaining = components[i+1:]

            # If target starts with '/', it's absolute
            if target.startswith('/'):
                target_components = target.split('/')
            else:
                # Target is relative to the directory containing the link
                # The directory containing the link is the parent of current
                last_slash = current.rfind('/')
                if last_slash == 0:
                    link_dir = '/'
                else:
                    link_dir = current[:last_slash]

                # Resolve target relative to link_dir
                if link_dir == '/':
                    target_components = [''] + target.split('/')
                else:
                    target_components = link_dir.split('/') + target.split('/')

            # Replace components: keep what we had before, add target components, then add remaining
            components = target_components + remaining

            # Reset current based on whether target is absolute or relative
            if target.startswith('/'):
                current = ''
            else:
                # We already built target_components to include the path
                # Now we need to process from the beginning
                last_slash = current.rfind('/')
                if last_slash == 0:
                    current = '/'
                else:
                    current = current[:last_slash]

            # Reset index to process new components
            i = 0
            continue

        i += 1

    # Normalize result
    if current == '':
        current = '/'

    # Remove trailing slash (except for root)
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

